'use client'

import Link from 'next/link'
import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getUserRole } from '@/lib/supabase/roles'
import { SUPPORT_CATEGORIES, type SupportTicketPriority, vendorSupportService } from '@/lib/vendor/support'
import { CatalogFeedback } from '../../components/CatalogFeedback'
import { SupportAttachments } from '../../components/SupportAttachments'
import type { SupportAttachment } from '@/lib/vendor/support'

export default function NewSupportTicketPage() { const [vendorId, setVendorId] = useState<string | null>(null); const [subject, setSubject] = useState(''); const [category, setCategory] = useState(SUPPORT_CATEGORIES[0]); const [priority, setPriority] = useState<SupportTicketPriority>('normal'); const [body, setBody] = useState(''); const [attachments, setAttachments] = useState<SupportAttachment[]>([]); const [error, setError] = useState(''); useEffect(() => { void createClient().auth.getUser().then(({ data: { user } }) => { if (user && (getUserRole(user) === 'vendor' || getUserRole(user) === 'admin')) setVendorId(user.id) }) }, []); async function submit(event: React.FormEvent) { event.preventDefault(); if (!vendorId || !subject.trim() || !body.trim()) { setError('Subject and message are required.'); return } const ticket = await vendorSupportService.create(vendorId, { subject: subject.trim(), category, priority, body: body.trim(), attachments }); window.location.href = `/vendor/support/${ticket.id}` } return <main className="vendor-page"><header className="vendor-header"><Link href="/vendor/support" className="logo logo-active">Furnish<span>AI</span></Link><span className="vendor-header-label">New support ticket</span></header><div className="operations-shell operations-form-shell"><div className="operations-heading"><div><p className="vendor-eyebrow">Support / New ticket</p><h1>How can we help?</h1><p>Share enough context for the marketplace team to respond efficiently.</p></div></div>{error ? <CatalogFeedback type="error">{error}</CatalogFeedback> : null}<form className="operations-form" onSubmit={(event) => void submit(event)}><label className="vendor-field"><span>Subject<b>*</b></span><input value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="Short description of the issue" /></label><div className="operations-form-grid"><label className="vendor-field"><span>Category</span><select value={category} onChange={(event) => setCategory(event.target.value)}>{SUPPORT_CATEGORIES.map((item) => <option key={item}>{item}</option>)}</select></label><label className="vendor-field"><span>Priority</span><select value={priority} onChange={(event) => setPriority(event.target.value as SupportTicketPriority)}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option></select></label></div><label className="vendor-field"><span>Message<b>*</b></span><textarea rows={8} value={body} onChange={(event) => setBody(event.target.value)} placeholder="Describe what happened and what you need from support." /></label><SupportAttachments attachments={attachments} onChange={setAttachments} /><div className="operations-form-actions"><Link href="/vendor/support" className="btn-skip">Cancel</Link><button type="submit" className="btn-next">Create ticket</button></div></form></div></main> }